usage:
import { LiquidGlass } from "./LiquidGlass";
import "./LiquidGlass.css";

<LiquidGlass
  size={180}
  bend={60}
  fringe={30}
  corner={40}
/>

notes:
/* A SHADER, NOT A FILTER. The photograph is a texture; every
   pixel asks a signed distance function how far it is from the
   ball's edge, so the bend, the rim light and the shadow all
   follow the same edge — even while it stretches. */
float d = sdf(p);                      /* < 0 inside the glass */
float edge = pow(1.0 - clamp(-d / bevel, 0.0, 1.0), 2.4);

/* the middle magnifies; the rim reads OUTWARD along the edge's
   normal, gathering what is just outside it — which is what
   a ball of glass on a table actually does */
vec2 q = c + (p - c) / 1.1 + n * edge * bevel * 1.1 * bend;

/* colour parts a hair at the rim */
g.r = read(q + off * fringe).r;  g.b = read(q - off * fringe).b;

/* a thin lit band inside the edge, bright where it faces the
   light, a weaker catch on the far side, and a soft shadow */
g += rim * (0.18 + 0.75 * max(dot(n, L), 0.0));
